//! Settings > Credits, "Software HumanityOS is built from" (2026-11-20): the copyright and licence
//! notices of every package the program links, read from THIRD-PARTY-NOTICES.txt beside it. Child
//! of settings.rs.
//!
//! The MIT, BSD and Apache-2.0 licences of those packages ask that their notices travel with the
//! program. Every download carries the file (scripts/lib/release-files.js); this puts it one press
//! away inside the app (CLAUDE.md, GUI-first: nobody has to find a text file in a folder). The
//! file is GENERATED by scripts/gen-third-party-notices.js, whose header comment documents the
//! format this parses: Part 1 (Rust packages) and Part 2 (web libraries) are entries, a title line
//! followed by indented "Key: value" lines, the first of them "Licence"; Part 3 is the licence
//! texts, each starting with a line of 80 dashes and its number, then a caption line, a blank line
//! and the text. `parses_the_committed_notices` holds the two together.

use std::path::{Path, PathBuf};
use std::sync::Arc;

use egui::RichText;
use humanity_core::i18n::{t, t_marked, tf};

use crate::gui::theme::Theme;
use crate::gui::widgets;

/// The file's name, beside the program (the folder above `data/`, as the download lays it out).
pub(crate) const FILE_NAME: &str = "THIRD-PARTY-NOTICES.txt";
/// The same file online, for a copy of the program that lost its own.
const ONLINE_URL: &str = "https://github.com/Shaostoul/Humanity/blob/main/THIRD-PARTY-NOTICES.txt";

/// One entry of Part 1 or Part 2: a package, or a web library.
#[derive(Debug, Clone, PartialEq)]
pub(crate) struct Entry {
    /// 1 for a Rust package, 2 for a web library.
    pub part: u8,
    /// "serde 1.0.229": the title line as written.
    pub title: String,
    /// Its "Key: value" lines, in order (Licence, Repository, Built into, Texts, Note).
    pub fields: Vec<(String, String)>,
    /// The numbers of the texts its "Texts" line names.
    pub texts: Vec<usize>,
}

/// One licence or notice text of Part 3.
#[derive(Debug, Clone, PartialEq)]
pub(crate) struct Text {
    pub number: usize,
    /// "LICENSE-MIT, from ahash 0.8.12 (and 2 more packages; ...)".
    pub caption: String,
    pub body: String,
}

/// The whole file, parsed.
#[derive(Debug, Clone, Default, PartialEq)]
pub(crate) struct Notices {
    pub entries: Vec<Entry>,
    pub texts: Vec<Text>,
}

impl Notices {
    /// The text numbered `n`, if the file has it.
    pub fn text(&self, n: usize) -> Option<&Text> {
        self.texts.iter().find(|t| t.number == n)
    }
}

/// A Part 3 marker line: 80 dashes, a space and the text's number.
fn text_marker(line: &str) -> Option<usize> {
    let rest = line.strip_prefix(&"-".repeat(80))?.strip_prefix(' ')?;
    rest.parse().ok()
}

/// "1 COPYING; 2 LICENSE-MIT, LICENSE-MIT.md" -> [1, 2].
fn text_numbers(value: &str) -> Vec<usize> {
    value
        .split("; ")
        .filter_map(|part| part.split(' ').next()?.parse().ok())
        .collect()
}

/// Parse the notices file (either line ending: a Windows checkout holds CRLF, a download LF;
/// `str::lines` drops the '\r' of a CRLF end).
pub(crate) fn parse(text: &str) -> Notices {
    let lines: Vec<&str> = text.lines().collect();
    let mut out = Notices::default();
    let mut part = 0u8;
    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];
        if let Some(n) = line.strip_prefix("PART ").and_then(|r| r.split('.').next()).and_then(|d| d.parse::<u8>().ok()) {
            part = n;
            i += 1;
            continue;
        }
        if part == 3 {
            if let Some(number) = text_marker(line) {
                let caption = lines.get(i + 1).copied().unwrap_or("").to_string();
                let mut j = i + 2;
                // The blank line between the caption and the text.
                if lines.get(j).is_some_and(|l| l.is_empty()) {
                    j += 1;
                }
                let start = j;
                while j < lines.len() && text_marker(lines[j]).is_none() {
                    j += 1;
                }
                let mut end = j;
                while end > start && lines[end - 1].is_empty() {
                    end -= 1;
                }
                out.texts.push(Text { number, caption, body: lines[start..end].join("\n") });
                i = j;
                continue;
            }
        } else if (part == 1 || part == 2)
            && !line.is_empty()
            && !line.starts_with(' ')
            && lines.get(i + 1).is_some_and(|next| next.starts_with("    Licence: "))
        {
            let mut entry = Entry { part, title: line.to_string(), fields: Vec::new(), texts: Vec::new() };
            let mut j = i + 1;
            while let Some(field) = lines.get(j).and_then(|l| l.strip_prefix("    ")) {
                if let Some((key, value)) = field.split_once(": ") {
                    if key == "Texts" {
                        entry.texts = text_numbers(value);
                    }
                    entry.fields.push((key.to_string(), value.to_string()));
                }
                j += 1;
            }
            out.entries.push(entry);
            i = j;
            continue;
        }
        i += 1;
    }
    out
}

/// Where the file is: beside `data/`, the folder above the one the app reads its data from (in a
/// download the program's own folder, in a checkout the repository's root).
pub(crate) fn notices_path(data_dir: &Path) -> PathBuf {
    match data_dir.parent() {
        Some(above) if !above.as_os_str().is_empty() => above.join(FILE_NAME),
        _ => PathBuf::from(FILE_NAME),
    }
}

/// What the viewer holds while it is open.
#[derive(Clone, Default)]
struct View {
    open: bool,
    // reuse: not a reuse; the file is read from disk each time the viewer opens and dropped when
    // it closes, so nothing is kept between openings (and a release's file never changes while it
    // runs).
    notices: Option<Result<Arc<Notices>, String>>,
    filter: String,
    selected: Option<usize>,
}

fn load(path: &Path) -> Result<Arc<Notices>, String> {
    let text = std::fs::read_to_string(path).map_err(|e| e.to_string())?;
    let notices = parse(&text);
    if notices.entries.is_empty() {
        return Err(format!("{} holds no entries", path.display()));
    }
    Ok(Arc::new(notices))
}

/// The section, drawn on Settings > Credits below HumanityOS's own licences.
pub(crate) fn draw_third_party(ui: &mut egui::Ui, theme: &Theme) {
    let id = ui.id().with("third_party_notices");
    let mut view: View = ui.data_mut(|d| d.get_temp(id)).unwrap_or_default();

    ui.label(
        RichText::new(t("credits.software_heading"))
            .size(theme.font_size_heading)
            .strong()
            .color(theme.text_primary()),
    );
    widgets::glossary_words(ui, theme, t_marked("credits.software_body"), theme.font_size_small, theme.text_secondary());
    ui.add_space(theme.spacing_sm);

    if !view.open {
        if widgets::Button::secondary(t("credits.software_show")).hint("credits.software_show_hint").show(ui, theme) {
            view.open = true;
            view.notices = Some(load(&notices_path(&humanity_core::storage::data_dir())));
        }
    } else {
        if widgets::Button::secondary(t("credits.software_hide")).hint("credits.software_hide_hint").show(ui, theme) {
            view = View::default();
        } else {
            draw_viewer(ui, theme, &mut view);
        }
    }

    ui.add_space(theme.spacing_md);
    ui.separator();
    ui.add_space(theme.spacing_sm);
    ui.data_mut(|d| d.insert_temp(id, view));
}

fn draw_viewer(ui: &mut egui::Ui, theme: &Theme, view: &mut View) {
    let notices = match &view.notices {
        Some(Ok(n)) => n.clone(),
        Some(Err(e)) => {
            let path = notices_path(&humanity_core::storage::data_dir());
            ui.label(
                RichText::new(tf("credits.software_missing", &[("path", &path.display()), ("error", e)]))
                    .size(theme.font_size_small)
                    .color(theme.warning()),
            );
            if widgets::Button::secondary(t("credits.software_online")).hint("credits.software_online_hint").show(ui, theme) {
                ui.ctx().open_url(egui::OpenUrl::new_tab(ONLINE_URL));
            }
            return;
        }
        None => return,
    };
    let rust = notices.entries.iter().filter(|e| e.part == 1).count();
    let web = notices.entries.len() - rust;
    ui.label(
        RichText::new(tf("credits.software_count", &[("packages", &rust), ("web", &web), ("texts", &notices.texts.len())]))
            .size(theme.font_size_small)
            .color(theme.text_muted()),
    );
    widgets::with_hint(ui, "credits.software_search_hint", |ui| widgets::search_bar(ui, theme, &mut view.filter, t("credits.software_search")));

    let needle = view.filter.to_lowercase();
    let shown: Vec<usize> = notices
        .entries
        .iter()
        .enumerate()
        .filter(|(_, e)| {
            needle.is_empty()
                || e.title.to_lowercase().contains(&needle)
                || e.fields.iter().any(|(k, v)| k == "Licence" && v.to_lowercase().contains(&needle))
        })
        .map(|(i, _)| i)
        .collect();
    if shown.is_empty() {
        ui.label(RichText::new(t("credits.software_none")).size(theme.font_size_small).color(theme.text_muted()));
    }
    let row_height = ui.text_style_height(&egui::TextStyle::Body) + theme.spacing_sm;
    egui::ScrollArea::vertical()
        .id_salt("third_party_list")
        .max_height(row_height * 10.0)
        .auto_shrink([false, true])
        .show_rows(ui, row_height, shown.len(), |ui, rows| {
            for &i in &shown[rows] {
                let e = &notices.entries[i];
                let licence = e.fields.iter().find(|(k, _)| k == "Licence").map(|(_, v)| v.as_str()).unwrap_or("");
                let label = format!("{}   ({licence})", e.title);
                let picked = view.selected == Some(i);
                widgets::with_hint(ui, "credits.software_row_hint", |ui| {
                    if ui.selectable_label(picked, RichText::new(label).size(theme.font_size_small)).clicked() {
                        view.selected = if picked { None } else { Some(i) };
                    }
                });
            }
        });
    ui.add_space(theme.spacing_sm);

    let Some(entry) = view.selected.and_then(|i| notices.entries.get(i)) else {
        ui.label(RichText::new(t("credits.software_pick")).size(theme.font_size_small).color(theme.text_muted()));
        return;
    };
    ui.label(RichText::new(&entry.title).strong().color(theme.accent()));
    egui::ScrollArea::vertical()
        .id_salt("third_party_texts")
        .max_height(row_height * 22.0)
        .auto_shrink([false, true])
        .show(ui, |ui| {
            for (key, value) in entry.fields.iter().filter(|(k, _)| k != "Texts") {
                ui.label(RichText::new(format!("{key}: {value}")).size(theme.font_size_small).color(theme.text_secondary()));
            }
            for n in &entry.texts {
                let Some(text) = notices.text(*n) else { continue };
                ui.add_space(theme.spacing_sm);
                ui.label(RichText::new(&text.caption).size(theme.font_size_small).strong().color(theme.text_primary()));
                ui.label(RichText::new(&text.body).monospace().size(theme.font_size_small).color(theme.text_primary()));
            }
        });
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = "THIRD-PARTY SOFTWARE NOTICES FOR HUMANITYOS\n\nFingerprint: 00\nBody checksum: 00\n\
        ================================================================================\n\
        PART 1. RUST PACKAGES BUILT INTO THE PROGRAMS (2)\n\
        ================================================================================\n\n\
        Which program each package is in, by the release download it comes in:\n    windows-x64: x86_64-pc-windows-msvc, the desktop app\n\n\
        adler2 2.0.1\n    Licence: 0BSD OR MIT OR Apache-2.0\n    Repository: https://example.org/adler2\n    Built into: every program (6)\n    Texts: 2 LICENSE-0BSD; 3 LICENSE-APACHE, LICENSE-APACHE.md\n\n\
        naga 24.0.0\n    Licence: MIT OR Apache-2.0\n    Repository: https://example.org/naga\n    Built into: every program (6)\n    Texts: 3 the standard Apache-2.0 text\n    Note: no licence file\n\n\
        ================================================================================\n\
        PART 2. WEB LIBRARIES THE WEBSITE SERVES (1)\n\
        ================================================================================\n\n\
        @noble/hashes 2.2.0\n    Licence: MIT\n    Served as: web/shared/vendor/noble-pq.bundle.js\n    Texts: 2 web/shared/vendor/noble-hashes-LICENSE.txt\n\n\
        ================================================================================\n\
        PART 3. THE LICENCE AND NOTICE TEXTS (2)\n\
        ================================================================================\n\n\
        -------------------------------------------------------------------------------- 2\n\
        Text 2: LICENSE-0BSD, from adler2 2.0.1\n\nCopyright (C) someone\n\n  indented line kept\n\n\
        -------------------------------------------------------------------------------- 3\n\
        Text 3: LICENSE-APACHE, from adler2 2.0.1\n\n                                 Apache License\n";

    #[test]
    fn parses_entries_fields_and_texts() {
        let n = parse(SAMPLE);
        assert_eq!(n.entries.len(), 3, "two packages and one web library; the programs table is not an entry");
        assert_eq!(n.entries[0].title, "adler2 2.0.1");
        assert_eq!(n.entries[0].part, 1);
        assert_eq!(n.entries[0].texts, vec![2, 3]);
        assert_eq!(n.entries[1].fields.last().unwrap(), &("Note".to_string(), "no licence file".to_string()));
        assert_eq!(n.entries[2].part, 2);
        assert_eq!(n.texts.len(), 2);
        assert_eq!(n.text(2).unwrap().body, "Copyright (C) someone\n\n  indented line kept", "inner blank lines and indentation kept, trailing blank lines dropped");
        assert_eq!(n.text(3).unwrap().body, "                                 Apache License", "a text's leading spaces are its own");
    }

    /// A Windows checkout holds the file with CRLF line ends, a download with LF: both parse alike.
    #[test]
    fn crlf_parses_like_lf() {
        assert_eq!(parse(&SAMPLE.replace('\n', "\r\n")), parse(SAMPLE));
    }

    #[test]
    fn the_file_sits_beside_the_data_folder() {
        assert_eq!(notices_path(Path::new("C:/Games/HumanityOS/data")), Path::new("C:/Games/HumanityOS").join(FILE_NAME));
        assert_eq!(notices_path(Path::new("data")), PathBuf::from(FILE_NAME), "a bare \"data\" (a test, or an unresolved folder) reads it from the working directory");
    }

    /// Draw the section alone in a panel, the way Settings > Credits does.
    fn frame(ctx: &egui::Context, theme: &Theme, events: Vec<egui::Event>) -> egui::FullOutput {
        frame_after(ctx, theme, 0.0, events)
    }

    /// One frame, `later` seconds after the last: a press and its release in the same instant are a
    /// click, a second apart a long press (egui's click time), so only the pointer's move waits.
    fn frame_after(ctx: &egui::Context, theme: &Theme, later: f64, events: Vec<egui::Event>) -> egui::FullOutput {
        let time = Some(ctx.input(|i| i.time) + later);
        let input = egui::RawInput { screen_rect: Some(egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(1000.0, 1600.0))), time, events, ..Default::default() };
        ctx.run(input, |ctx| {
            egui::CentralPanel::default().show(ctx, |ui| draw_third_party(ui, theme));
        })
    }

    fn click(ctx: &egui::Context, theme: &Theme, what: &str) -> egui::FullOutput {
        let mut out = frame(ctx, theme, Vec::new());
        for _ in 0..2 {
            out = frame(ctx, theme, Vec::new());
        }
        let pos = crate::gui::screen_surface::find_text_in_shapes(&out.shapes, what).unwrap_or_else(|| panic!("{what:?} is drawn")).rect.center();
        let m = egui::Modifiers::default();
        frame_after(ctx, theme, 1.0, vec![egui::Event::PointerMoved(pos)]);
        frame(ctx, theme, vec![egui::Event::PointerButton { pos, button: egui::PointerButton::Primary, pressed: true, modifiers: m }]);
        frame(ctx, theme, vec![egui::Event::PointerButton { pos, button: egui::PointerButton::Primary, pressed: false, modifiers: m }]);
        frame(ctx, theme, Vec::new())
    }

    /// The section WORKS, not just draws: pressing "Show the notices" reads the real file and lists
    /// its packages, and pressing a package shows its licence texts. Measured on what is drawn.
    /// Seen red 2026-11-20 with the text bodies' label taken out: "the Apache-2.0 text itself is
    /// drawn" failed while everything before it (the count, the rows, the heading, the caption)
    /// passed.
    #[test]
    fn show_the_notices_then_a_package_draws_its_texts() {
        let ctx = egui::Context::default();
        let theme = crate::gui::theme::load_theme();
        let before = frame(&ctx, &theme, Vec::new());
        let drawn = |out: &egui::FullOutput| crate::gui::pages::apps::tests::texts(out).into_iter().map(|(t, _)| t).collect::<Vec<_>>();
        let is_row = |t: &String| t.contains("   (") && t.ends_with(')');
        let show = t("credits.software_show");
        assert!(drawn(&before).iter().any(|s| s == show), "the button is drawn");
        assert!(!drawn(&before).iter().any(is_row), "no list before it is asked for");

        let shown = click(&ctx, &theme, show);
        let texts = drawn(&shown);
        assert!(texts.iter().any(|t| t.contains("Rust packages and")), "the count line is drawn: {:?}", &texts[..texts.len().min(12)]);
        // The file sorts by name: ab_glyph, an Apache-2.0 package, comes first.
        let row = texts.iter().find(|t| is_row(t)).cloned().expect("the packages are listed");
        assert!(row.starts_with("ab_glyph "), "the first row is the first package in the file: {row}");
        assert!(!texts.iter().any(|t| t.starts_with("Text ")), "no texts before a package is chosen");

        let picked = click(&ctx, &theme, &row);
        let texts = drawn(&picked);
        let title = row.split("   (").next().unwrap();
        assert!(texts.iter().any(|t| t == title), "the chosen package's name is drawn as the heading of its texts");
        assert!(texts.iter().any(|t| t.starts_with("Licence: Apache-2.0")), "its licence line is drawn");
        assert!(texts.iter().any(|t| t.starts_with("Text ")), "a text's caption is drawn: {:?}", &texts[texts.len().saturating_sub(8)..]);
        assert!(texts.iter().any(|t| t.contains("Apache License")), "the Apache-2.0 text itself is drawn");
    }

    /// The committed file, written by scripts/gen-third-party-notices.js, parses into what its own
    /// headings say: every entry the generator wrote, every text, and every text an entry names.
    /// Seen red 2026-11-20 with the parser taking any indented line (not "    Licence: ") as the
    /// start of an entry: "every Rust package, left: 747, right: 746" (Part 1's table of programs
    /// counted as a package), and the sample test "left: 4, right: 3".
    #[test]
    fn parses_the_committed_notices() {
        let path = Path::new(env!("HUMANITY_REPO_ROOT")).join(FILE_NAME);
        let text = std::fs::read_to_string(&path).expect("THIRD-PARTY-NOTICES.txt is committed at the repo root");
        let n = parse(&text);
        let count = |part: &str| -> usize {
            let line = text.lines().find(|l| l.starts_with(part)).unwrap_or_else(|| panic!("no {part} heading"));
            let open = line.rfind('(').expect("a count in brackets");
            line[open + 1..].trim_end_matches(['\r', ')']).parse().expect("a number")
        };
        assert_eq!(n.entries.iter().filter(|e| e.part == 1).count(), count("PART 1."), "every Rust package");
        assert_eq!(n.entries.iter().filter(|e| e.part == 2).count(), count("PART 2."), "every web library");
        assert_eq!(n.texts.len(), count("PART 3."), "every text");
        assert!(n.entries.len() > 300, "hundreds of packages");
        for e in &n.entries {
            assert!(!e.texts.is_empty(), "{} names no text", e.title);
            for t in &e.texts {
                assert!(n.text(*t).is_some_and(|x| !x.body.is_empty()), "{} names text {t}, which the file does not hold", e.title);
            }
        }
        // The CRLF form a Windows checkout holds parses alike.
        assert_eq!(parse(&text.replace("\r\n", "\n").replace('\n', "\r\n")), n);
    }
}
